/**
 * A GIF is drawn as a picture; a file somebody chose keeps its name.
 *
 * Reported with a screenshot: "counter-strike-rage-gif.mp4 - 34 KB" written
 * underneath a reaction GIF.
 *
 * Written because the audit found this one had only ever been read, not run.
 * Nobody had sent a GIF since the change went out - the newest attachment on
 * the live server still predated it - so "the filename is gone" was a claim
 * about a ternary rather than about the screen.
 *
 * Both halves, because hiding it everywhere would also satisfy the report and
 * would be wrong: for a file somebody picked off their own disk the name is
 * the one they know it by and the size says what they are about to spend.
 */
const { signIn } = require('../lib.cjs')

/*
 * Two real files, uploaded before they are attached.
 *
 * This used to name /uploads/pretend-gif.mp4 - a path that did not exist and
 * that nobody had uploaded - above a comment saying the file need not exist.
 * That was true when it was written, and it was true because of the hole this
 * spec had accidentally demonstrated: the server took the path out of the
 * message and believed it, so anybody could pin any file to a message of
 * their own.
 *
 * The uploads ledger closed that on 26 Aug, and a message can now only carry
 * a file its sender uploaded. So the send is refused, nothing renders, and
 * every check below fails - with the app behaving exactly as it should.
 *
 * The spec was wrong, not the app. It uploads first now, which is also what
 * the picker itself does.
 *
 * The bytes are the smallest thing the sniffer will accept as each type: an
 * mp4 is judged by "ftyp" at offset four, a PNG by its eight-byte header.
 * The photo is padded past a kilobyte because the caption it has to produce
 * says KB, and anything shorter is written as bytes.
 */
const MP4 = '00000018' + '66747970' + '6d703432'.repeat(2) + '00'.repeat(4000)
/*
 * A picture that actually decodes.
 *
 * This was a PNG signature followed by four thousand bytes of nothing,
 * which no browser will draw - so the app did the right thing with it and
 * said the file was no longer here, and the spec read that as the name
 * being missing. A one-pixel PNG, padded with a private chunk that
 * decoders skip, so it is both a real picture and large enough for a size
 * to be worth printing under it.
 */
const PNG = ''

const upload = (token, filename, mime, hex) => `(async () => {
  const hex = ${JSON.stringify(hex)}
  const bytes = new Uint8Array(hex.length / 2)
  for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(hex.substr(i * 2, 2), 16)
  const r = await fetch('/api/upload', {
    method: 'POST',
    headers: {
      'content-type': ${JSON.stringify(mime)},
      'x-filename': ${JSON.stringify(filename)},
      authorization: 'Bearer ' + ${JSON.stringify(token)},
    },
    body: bytes,
  })
  return { status: r.status, body: await r.json().catch(() => null) }
})()`

/** The stored name inside a signed /uploads link - what the img src will carry. */
const storedName = (url) => String(url || '').split('?')[0].split('/').pop()

/* Sent over the gateway, which is the only way a message with an attachment
   arrives. */
const sendWith = (token, attachments) => `(() => new Promise((resolve) => {
  const s = new WebSocket('ws://' + location.host + '/gateway')
  s.onopen = () => s.send(JSON.stringify({ t: 'hello', token: ${JSON.stringify(token)} }))
  s.onmessage = (e) => {
    const m = JSON.parse(e.data)
    if (m.t === 'ping') return s.send(JSON.stringify({ t: 'pong' }))
    if (m.t === 'ready') {
      const ch = (m.channels || []).find((c) => c.kind === 'text')
      if (!ch) { s.close(); return resolve({ ok: false, why: 'no text channel' }) }
      s.send(JSON.stringify({ t: 'send', channelId: ch.id,
        body: ${JSON.stringify('')}, attachments: ${JSON.stringify(attachments)},
        nonce: 'att-' + Math.random().toString(36).slice(2) }))
      setTimeout(() => { s.close(); resolve({ ok: true }) }, 900)
    }
  }
  setTimeout(() => resolve({ ok: false, why: 'never became ready' }), 9000)
}))()`

const CAPTION = `(() => {
  const rows = [...document.querySelectorAll('.msg')]
  const find = (name) => {
    const row = rows.find((r) => r.querySelector('.att img, .att video, .attf'))
    return row
  }
  /* The outermost box of each attachment: a picture is a button with the
     picture in it, wrapped in one that also carries the name. */
  const attach = [...document.querySelectorAll(
    '.attpic, .attgif, .attv, .atta, .attf, .att:not(.attpic > .att)')]
  return attach.map((a) => ({
    caption: a.querySelector('.attn') ? a.querySelector('.attn').textContent.trim() : null,
    /* The picture may be the element itself: a GIF is drawn as a video
       with the class on it rather than as a wrapper round one. */
    src: (a.matches('img, video') ? a : a.querySelector('img, video') || {}).src || '',
  }))
})()`

module.exports = {
  name: 'gif-has-no-filename',
  width: 1280,
  height: 900,

  async run({ js, until, wait, win, check, base }) {
    await win.loadURL(base + '/')
    const setup = await signIn(js, { owner: 'JacksFO' })
    check('the server can be set up', setup.ok === true, setup.why)

    const token = setup.me?.token ?? ''

    /* Uploaded first, because only a file you uploaded can be attached. */
    const gifUp = await js(upload(token, 'counter-strike-rage-gif.mp4', 'video/mp4', MP4))
    check('a GIF can be uploaded', gifUp.status === 200, gifUp)
    const photoUp = await js(upload(token, 'holiday-photo.png', 'image/png', PNG))
    check('and so can a photo', photoUp.status === 200, photoUp)

    const gifStored = storedName(gifUp.body && gifUp.body.url)
    const photoStored = storedName(photoUp.body && photoUp.body.url)

    /* One of each, sent as the same person into the same channel. */
    const gif = await js(sendWith(token, [{
      url: gifUp.body && gifUp.body.url,
      filename: 'counter-strike-rage-gif.mp4',
      isGif: true,
    }]))
    check('a GIF can be sent', gif.ok === true, gif)

    const file = await js(sendWith(token, [{
      url: photoUp.body && photoUp.body.url,
      filename: 'holiday-photo.png',
      isGif: false,
    }]))
    check('and a file somebody chose can be sent', file.ok === true, file)

    await win.loadURL(base + '/')
    await until('the attachments', `document.querySelectorAll('.att, .attgif, .attv, .atta, .attf').length >= 2`, 15000)
    await wait(1200)

    const shown = await js(CAPTION)
    console.log('      ' + JSON.stringify(shown))
    check('both arrived', shown.length >= 2, shown)

    // Matched on the stored name, which is a uuid the server chose - the
    // signature on the link is re-made on every read and is not stable.
    const gifBox = shown.find((a) => a.src.indexOf(gifStored) !== -1)
    const fileBox = shown.find((a) => a.src.indexOf(photoStored) !== -1)
    check('the GIF is on screen', !!gifBox, shown)
    check('and so is the photo', !!fileBox, shown)

    /* The report. */
    check('the GIF has no filename written under it',
      gifBox && gifBox.caption === null, gifBox)

    /*
     * And a picture somebody attached themselves says nothing either.
     *
     * This used to be the half that stopped the fix going too far: a GIF was
     * a reaction and needed no name, a file off somebody's own disk kept one.
     * Asked for the other way since, and the other way is right - a picture
     * in a conversation is the thing itself, and a caption under it is words
     * about something already on the screen. A file with nothing to show
     * still says what it is; that is the row at the end of Attachment.tsx,
     * and there the name is all there is to go on.
     */
    check('and a picture somebody attached says nothing under it either',
      fileBox && !fileBox.caption, fileBox)
  },
}
